package local.headunit.diplay;
import android.content.*;import android.media.*;import android.os.*;import java.io.Closeable;import java.util.*;import org.json.*;

/** Firmware-audited navigation stream. Does not impersonate a phone hang-up or change car sources. */
public final class AudioRouting implements Closeable {
 private final Context context;private final LegacyMedia media;private final int secondMusic;private final BydCallUsbAssert callUsbAssert;
 private final Map<String,PlaybackFocus> focus=new HashMap<String,PlaybackFocus>();private boolean closed;private int callAudioUsers,previousCallMode=AudioManager.MODE_NORMAL,previousCallVolume,callMaxVolume;private boolean previousCallSpeaker,ownsCallVolume,ownsCallMode,ownsCallSpeaker;
 public AudioRouting(Context c,LegacyMedia m){context=c.getApplicationContext();media=m;secondMusic=secondMusic(c);callUsbAssert=secondMusic==10?new BydCallUsbAssert(c):null;if(callUsbAssert!=null)callUsbAssert.start();for(final String role:new String[]{"media","navigation","assistant","call"}){
  if(role.equals("assistant")||(role.equals("navigation")&&secondMusic==10))continue;
  int gain=role.equals("call")?CallAudioFocusPolicy.gain(secondMusic==10):role.equals("media")?AudioManager.AUDIOFOCUS_GAIN:AudioManager.AUDIOFOCUS_GAIN_TRANSIENT_MAY_DUCK;
  final int focusStream=role.equals("call")?LegacyAudioPolicy.callFocusStream(secondMusic):AudioManager.STREAM_MUSIC;
  focus.put(role,new PlaybackFocus(c,new PlaybackFocus.Volume(){public void set(float value){media.setRoleVolume(role,value);if(role.equals("media"))media.setRoleVolume("assistant",value);}},gain,role,focusStream));
 }try{MainActivity.record(context,"AUDIO_ROUTING",new JSONObject().put("navigationStream",stream("navigation")).put("nativeNavigation",secondMusic==10).put("assistantStream",stream("assistant")).put("callStream",stream("call")).put("callFocusStream",LegacyAudioPolicy.callFocusStream(secondMusic)).put("callDownlinkRoute",secondMusic==10?"airplay_telephony_pcm_on_android_media_preserve_current_mcu_source":"airplay_telephony_on_android_phone_stream").put("oemPhoneStateControl",secondMusic==10?"not_sent_preserve_current_source":"not_applicable").put("callFocusPolicy",secondMusic==10?"client_transient_media_focus":"client_full_gain_phone_stream").put("callAndroidRoutePolicy",secondMusic==10?"preserve_mode_speaker_and_mcu_source":"request_in_call_mode_and_speakerphone"));}catch(Exception ignored){}}
 public Context captureContext(){return context;}
 public int stream(String role){return LegacyAudioPolicy.stream(role,secondMusic);}
 public synchronized void beginCallAudio(){if(closed)return;if(callAudioUsers++>0)return;AudioManager a=(AudioManager)context.getSystemService(Context.AUDIO_SERVICE);int callStream=stream("call");boolean platformPhoneStrategy=LegacyAudioPolicy.usesPlatformPhoneStrategy(secondMusic);try{previousCallMode=a.getMode();previousCallSpeaker=a.isSpeakerphoneOn();previousCallVolume=a.getStreamVolume(callStream);callMaxVolume=a.getStreamMaxVolume(callStream);ownsCallVolume=false;ownsCallMode=false;ownsCallSpeaker=false;}catch(Exception e){callAudioUsers=0;callRouteLog("call_state_read_failed",previousCallMode,a.getMode(),e.getClass().getSimpleName());return;}
  try{if(callMaxVolume>0){a.setStreamVolume(callStream,callMaxVolume,0);ownsCallVolume=a.getStreamVolume(callStream)==callMaxVolume;}}catch(Exception e){callRouteLog("call_max_volume_request_failed",previousCallMode,a.getMode(),e.getClass().getSimpleName());}
  if(platformPhoneStrategy){try{a.setMode(LegacyAudioPolicy.callMode());ownsCallMode=a.getMode()==LegacyAudioPolicy.callMode();}catch(Exception e){callRouteLog("in_call_mode_request_failed",previousCallMode,a.getMode(),e.getClass().getSimpleName());}try{a.setSpeakerphoneOn(LegacyAudioPolicy.callSpeakerphone());ownsCallSpeaker=a.isSpeakerphoneOn()==LegacyAudioPolicy.callSpeakerphone();}catch(Exception e){callRouteLog("phone_speaker_route_request_failed",previousCallMode,a.getMode(),e.getClass().getSimpleName());}callRouteLog("android_phone_strategy_requested",previousCallMode,a.getMode(),null);}else callRouteLog("android_media_route_preserving_current_mcu_source",previousCallMode,a.getMode(),null);
  if(callUsbAssert!=null){callUsbAssert.callStarted();CallToneProbe.callStarting();}}
 public synchronized void endCallAudio(){if(callAudioUsers<=0)return;if(--callAudioUsers>0)return;AudioManager a=(AudioManager)context.getSystemService(Context.AUDIO_SERVICE);try{int callStream=stream("call");if(ownsCallMode&&a.getMode()==LegacyAudioPolicy.callMode())a.setMode(previousCallMode);if(ownsCallSpeaker&&a.isSpeakerphoneOn()==LegacyAudioPolicy.callSpeakerphone())a.setSpeakerphoneOn(previousCallSpeaker);if(ownsCallVolume&&a.getStreamVolume(callStream)==callMaxVolume)a.setStreamVolume(callStream,previousCallVolume,0);callRouteLog("call_audio_route_restored",previousCallMode,a.getMode(),null);}catch(Exception e){callRouteLog("call_route_restore_failed",previousCallMode,a.getMode(),e.getClass().getSimpleName());}finally{ownsCallVolume=false;ownsCallMode=false;ownsCallSpeaker=false;previousCallMode=AudioManager.MODE_NORMAL;previousCallVolume=0;callMaxVolume=0;previousCallSpeaker=false;if(callUsbAssert!=null){callUsbAssert.callEnded();CallToneProbe.callEnded();}}}
 private void callRouteLog(String detail,int before,int after,String error){try{AudioManager a=(AudioManager)context.getSystemService(Context.AUDIO_SERVICE);int callStream=stream("call");boolean platformPhoneStrategy=LegacyAudioPolicy.usesPlatformPhoneStrategy(secondMusic);JSONObject j=new JSONObject().put("detail",detail).put("previousMode",before).put("activeMode",after).put("platformPhoneStrategy",platformPhoneStrategy).put("modePreservedForOemRoute",!platformPhoneStrategy&&before==after).put("speakerphoneForced",platformPhoneStrategy).put("activeSpeakerphone",a.isSpeakerphoneOn()).put("speakerphonePreservedForOemRoute",!platformPhoneStrategy&&a.isSpeakerphoneOn()==previousCallSpeaker).put("previousSpeakerphone",previousCallSpeaker).put("outputStream",callStream).put("focusStream",LegacyAudioPolicy.callFocusStream(secondMusic)).put("clientFocusRequested",LegacyAudioPolicy.usesClientCallFocus(secondMusic)).put("previousVolume",previousCallVolume).put("activeVolume",a.getStreamVolume(callStream)).put("maxVolume",a.getStreamMaxVolume(callStream)).put("volumeMaxAccepted",ownsCallVolume).put("oemBtPhoneSourceRequested",false).put("audioSystem",AudioSystemEvidence.routingSnapshot(a,context));if(error!=null)j.put("error",error);MainActivity.record(context,"CALL_AUDIO_ROUTE",j);}catch(Exception ignored){}}
 public static void logCallOutput(Context c,AudioTrack t,int stream,String phase,long written,long head,float gain){try{AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);JSONObject j=new JSONObject().put("phase",phase).put("mode",a.getMode()).put("stream",stream).put("streamVolume",a.getStreamVolume(stream)).put("streamMax",a.getStreamMaxVolume(stream)).put("speakerphone",a.isSpeakerphoneOn()).put("bluetoothSco",a.isBluetoothScoOn()).put("bluetoothA2dp",a.isBluetoothA2dpOn()).put("wiredHeadset",a.isWiredHeadsetOn()).put("microphoneMuted",a.isMicrophoneMute()).put("musicActive",a.isMusicActive()).put("routePolicy",AudioRouteProbe.snapshot(a)).put("audioSystem",AudioSystemEvidence.routingSnapshot(a,c)).put("trackPresent",t!=null).put("writtenBytes",written).put("playbackHeadFrames",head).put("trackGain",gain).put("evidenceScope","AudioTrack queue consumption only; no amplifier loopback");if(t!=null)j.put("trackState",t.getState()).put("playState",t.getPlayState()).put("sessionId",t.getAudioSessionId()).put("nativeRate",AudioTrack.getNativeOutputSampleRate(stream));MainActivity.record(c,"CALL_OUTPUT_DIAG",j);}catch(Exception ignored){}}
 public float packet(String role){PlaybackFocus f; synchronized(this){if(closed)return 0;f=focus.get(role.equals("assistant")?"media":role);}return f==null?1:f.packet();}
 public void playbackEnded(String role){PlaybackFocus f,mediaFocus;synchronized(this){if(closed)return;f=focus.get(role.equals("assistant")?"media":role);mediaFocus=role.equals("call")?focus.get("media"):null;}if(f!=null)f.playbackEnded();if(mediaFocus!=null)mediaFocus.foreground();}
 public synchronized void foreground(){if(!closed)for(PlaybackFocus f:focus.values())f.foreground();}
 public synchronized void close(){if(closed)return;closed=true;if(callUsbAssert!=null)callUsbAssert.close();for(PlaybackFocus f:focus.values())f.close();}
 public static int secondMusic(Context c){try{if(Build.VERSION.SDK_INT!=17||!"MX9A0".equals(Build.MODEL)||c.getPackageManager().getPackageInfo("com.byd.multimediaservice",0).versionCode!=382)return -1;int value=AudioManager.class.getField("STREAM_MUSIC_SECOND").getInt(null);return value==10?value:-1;}catch(Exception e){return -1;}}
 public static JSONObject evidence(Context c)throws Exception{AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);int second=secondMusic(c);JSONArray streams=new JSONArray();for(java.lang.reflect.Field f:AudioManager.class.getFields()){if(!f.getName().startsWith("STREAM_")||f.getType()!=Integer.TYPE)continue;JSONObject item=new JSONObject().put("name",f.getName());try{int stream=f.getInt(null);item.put("id",stream).put("volume",a.getStreamVolume(stream)).put("max",a.getStreamMaxVolume(stream));}catch(Exception e){item.put("error",e.getClass().getSimpleName());}streams.put(item);}return new JSONObject().put("streams",streams).put("auditedNavigationStream",second).put("callDownlinkStream",LegacyAudioPolicy.stream("call",second)).put("callFocusStream",LegacyAudioPolicy.callFocusStream(second)).put("clientCallFocus",LegacyAudioPolicy.usesClientCallFocus(second)).put("callFocusPolicy",second==10?"client_transient_media_focus":"client_full_gain_phone_stream").put("oemPhoneStateControl",second==10?"not_sent_preserve_current_source":"not_applicable").put("callAndroidRoutePolicy",second==10?"preserve_mode_speaker_and_mcu_source":"request_in_call_mode_and_speakerphone").put("legacyRouting",AudioRouteProbe.snapshot(a)).put("audioSystem",AudioSystemEvidence.routingSnapshot(a,c));}
}
